alias=dict(zip('奥 洛 蕾 雷 卡 阿 韦 红 霞 蓝 牛 瑟 慎 约 狼 沃 芸 妖 凯 蛙 人 蔚 稻 石 螳 黛 鸡 大蓝 莉 木 大红 EZ 月 索 树 塔 纳 电 艾 德 拉 翁 龙 女 炮 蛛'.split(),'奥恩 洛 蕾欧娜 雷克塞 卡蜜尔 阿卡丽 韦鲁斯 绯红树怪 霞 苍蓝哨戒 阿利斯塔 瑟庄妮 慎 约里克 暗影狼 沃里克 芸阿娜 乐芙兰 凯尔 魔沼蛙 赫卡里姆 蔚 费德提克 远古石甲虫 卡兹克 黛安娜 深红锋喙鸟 苍蓝雕纹魔像 莉莉娅 阿木木 绯红印记树怪 伊泽瑞尔 厄斐琉斯 索拉卡 茂凯 塔里克 纳尔 凯南 艾希 德莱文 拉露恩 艾翁 远古巨龙 凯特琳 崔丝塔娜 伊莉丝'.split()))
alias["希"]="希维尔"
def B(s):return [alias.get(n,n) for n in s.split()]
major=['永恒之森','月蚀骑士','迅捷射手','重装战士','护卫','花仙子','斗士','峡谷野怪','狂战士','主宰','猎人','野兽之灵','日蚀骑士','地狱火','黑荆棘','裁决使','法师','绝命花妖','神谕','召唤师','灵魂莲华','魔女']
def calculate(board,emblems=None,evolve=False):
 c=Counter()
 for n in set(board):
  for t in ht[n]:c[t]+=2 if n=='远古巨龙' and t=='峡谷野怪' else 1
 if evolve and '卡兹克' in board:c['裁决使']+=1
 for n,t in (emblems or {}).items():
  assert n in board and t not in ht[n],(n,t)
  c[t]+=1
 active={}
 for t,n in c.items():
  if t not in major:continue
  ts=sorted({int(x) for x in str(traits[t]['numList']).split('|') if x.isdigit()})
  valid=[v for v in ts if v<=n]
  if valid:active[t]=max(valid)
 if c['日蚀骑士']>=3 and c['月蚀骑士']>=3:active['日月双蚀']=1
 return dict(c),active

def state(s,why,em=None,evo=False):return {'board':B(s),'why':why,'emblems':{alias.get(k,k):v for k,v in (em or {}).items()},'evolve':evo}
