route('114',{4:state('霞 韦 洛 慎','2迅射＋2地狱火＋2花仙，先让后排有前排可依赖。'),5:state('霞 韦 洛 慎 凯','凯尔补3迅射，缺他不硬塞一星；额外输出位也会挤压坦度。'),6:state('霞 韦 洛 慎 凯 瑟','瑟庄妮＋洛补2主宰，不把她和凯尔仅两张日蚀说成开羁绊。'),7:state('月 霞 鸡 大红 大蓝 黛 木','有迅射纹章时给大红（来源明确）：3名天然迅射＋纹章达到4迅射；另有3野怪、2月蚀、2重装。此时仍不是5迅射。这是一整组换阵，不能仅凭有纹章在7级强找齐四费。',{'大红':'迅捷射手'}),8:state('月 霞 鸡 大红 大蓝 黛 木 韦','韦鲁斯补第5迅射，同时与阿木木开2地狱火。大红既当前排/副C又贡献射手档位，比额外塞一个脆弱射手省位。',{'大红':'迅捷射手'}),9:state('月 霞 鸡 大红 大蓝 黛 木 韦 洛','洛同时开2主宰（阿木木）与2花仙（霞）；重装2→3没有升档。可视情况换更强五费，但要明确损失这两个小羁绊。',{'大红':'迅捷射手'})})
route('116',{4:state('奥 妖 人 螳','3永森给植物；螳螂需要参与击杀完成进化，初始没有裁决职业。此4人口含两张三费，仅在来牌支持时使用，不是必成开局。'),5:state('奥 妖 人 螳 稻','稻草人同时接奥恩的2护卫、妖姬的2法师；螳螂先积累进化，星级与装备不到位不硬赌。'),6:state('奥 妖 人 螳 稻 黛','黛安娜＋人马开2重装，增加近战主C生存时间；此时没有第二月蚀，不计月蚀增益。'),7:state('奥 人 螳 稻 黛 EZ 索','要求螳螂已进化裁决：与EZ、索拉卡开3裁决；稻草人＋索拉卡开2花妖；奥恩＋稻草人2护卫、人马＋黛安娜2重装、奥恩＋人马＋EZ3森。移除妖姬会丢2法师。',evo=True),8:state('奥 人 螳 稻 黛 EZ 索 电','凯南补4裁决，并提供另一法系输出。也可补月男，变2月蚀但停3裁决；当主C是螳螂时要比较真实伤害档位与月蚀收益，不能只看多一个羁绊。',evo=True),9:state('奥 人 螳 稻 黛 EZ 索 电 月','月男与黛安娜开2月蚀；他只是一种余装副C/连接位，只有1名迅射，不具有迅射成型收益。也可选择塔里克/艾翁保护主C。',evo=True)})
route('112',{4:state('韦 阿 慎 洛','3地狱火提供商店引燃，洛先当质量前排；不是立即拥有5火灼烧。'),5:state('韦 阿 慎 洛 瑟','瑟庄妮＋洛开2主宰，帮助经济引擎争取时间。'),6:state('韦 阿 慎 洛 瑟 女','女警是带装备的暂时输出位，目前只有1猎人；不是为了羁绊而必挂，谁先两星谁打工。'),7:state('韦 阿 慎 女 希 木 蔚','希维尔携地狱火纹章（来源明确）让4天然火变5火；女警＋希维尔2猎人，蔚＋希维尔2野兽，蔚＋阿木木2主宰。希维尔的弹射能把地狱火的功能带到更多目标。',{'希':'地狱火'}),8:state('韦 慎 希 木 蔚 电 艾 大蓝','艾希替女警保2猎人；凯南替阿卡丽保5地狱火，增加法系输出；大蓝是高质量前排并为9级重装留位。这需要高费自然来牌，不能把到8级等同必有五费。',{'希':'地狱火'}),9:state('韦 慎 希 木 蔚 电 艾 大蓝 塔','塔里克与大蓝开2重装，并可绑定重要携带者。保5火、2猎人、2野兽、2主宰；不能随便卖韦鲁斯而让5火跌成4。',{'希':'地狱火'})})
route('113',{4:state('奥 霞 牛 洛','3森植物＋2花仙用于过渡；后期拉露恩为法系主C，早期装备要分清物理与法系去向。'),5:state('奥 霞 牛 洛 人','人马＋洛开2重装，森林仅4计数还在3档。'),6:state('奥 霞 牛 洛 人 妖','妖姬补5森，增加植物；她也可临时带拉露恩的法系/回蓝装备，但转移需要实际卖牌或拆卸条件。'),7:state('奥 霞 牛 洛 人 妖 黛','黛安娜是未来月蚀＋重装连接牌；此处月蚀仍1、重装3，暂未新增档位。若她一星明显弱，可先留更强打工牌，不能为了未来提前降战力。'),8:state('牛 人 黛 大蓝 塔 纳 拉 峡谷迅捷蟹','高费到位才整组重组：牛/人/纳3森，牛/纳2斗，人/黛/大蓝/塔4重，黛/拉2月蚀。河蟹暂占巨龙前的一格；此时仅2野怪，尚未开3。'),9:state('牛 人 黛 大蓝 塔 纳 拉 龙','用占2人口的巨龙替换河蟹，正好消耗新增一人口，野怪2→3；拉露恩法系、巨龙物理、纳尔功能近战，装备分流。')})
route('89',{4:state('红 蓝 峡谷迅捷蟹 约','先用3野怪＋2主宰过渡；九五是资源终局，不是从4级开始强买所有未来牌。'),5:state('红 蓝 峡谷迅捷蟹 石 狼','5野怪以商店资源助运营；若掉血严重，应先保质量，不能只为商店收益拆强牌。'),6:state('红 蓝 峡谷迅捷蟹 石 鸡 约','5野怪＋2主宰＋2召唤师。装备先给打工输出，能否上9取决于血量和经济，不由当前羁绊名字决定。'),7:state('蓝 峡谷迅捷蟹 石 鸡 大蓝 大红 狼','到7野怪稳中期；若主C已追三、当前战力成熟，可留原体系，不强行转九五。'),8:state('大蓝 木 蔚 希 塔 电 树 德','这只是高费到位后的暂存8人口盘：2重装、2主宰、2地狱火、2野兽。无这些高费时沿原盘上9，绝不先卖原主C等商店。'),9:state('大蓝 木 塔 电 树 德 翁 龙','移除蔚/希维尔、加入巨龙/艾翁：失去2野兽，获得3野怪以及高费技能质量。保留大蓝＋塔2重、树＋阿木木2主、凯南＋阿木木2火。')})
# Core explanations cover every S/A comp; source roles are audited rather than blindly accepted.
cores={
'99':('鸡哥持续普攻召唤物输出；石甲虫/大蓝承伤','3野怪阿尔法→5野怪商店→7野怪战斗成长，是三个不同收益。鸡哥每次普攻驱动小鸡攻击，攻速和活着的时间都重要。','小红、小蓝、暗影狼、魔沼蛙多为野怪计数位；大红可做物理副C。约里克只在能接2主宰/2召唤师的阶段高效，后期不必固定保留。','与小红/小蓝共用野怪前排与阿尔法引擎，但鸡哥攻速装不能直接等同小红的技能装备。'),
'104':('三星小红是输出核心；石甲虫/高费前排提供施法时间','小红技能是物理技能伤害并自带短时灼烧重伤；其专属霸符按施法成长，回蓝与持续施法比盲堆攻速更有直接机制关系。','小蓝可作法系副C，但不自动必须三星；后期纳尔/塔里克分别连接斗士/重装，巨龙保持野怪计数。','与小蓝共用坦装和野怪壳；与鸡哥共用棋子却不完全共用主C三件套。'),
'107':('三星小蓝是法系核心；石甲虫/大蓝延长引导','小蓝持续引导且持续削减目标魔抗，神谕回蓝与前排生存支撑长战斗；双大天使体现时间型输出思路。','大蓝同时给野怪、神谕、重装连接；小红没追成可换，不能为了野怪名额保一个无装备弱后排。','与鸡哥/小红共享前排；其法系装备可由其他法系打工，但已追三星后不可无损转月男。'),
'87':('三星沃里克＋关键前排牛头；暗影狼是低成本连接位','狼人技能自疗并叠攻速，4狂战的伤害与吸血、前排的存活时间相互支持；2黑荆棘有祭品成本，格子要避开主C和主坦。','雷克塞连接黑荆棘和斗士；暗影狼连接狂战和野怪；大红＋大蓝组合接3野怪，黛安娜＋大蓝接2重装。','与野怪共用暗影狼/大红/大蓝；与近战阵容共享吸血防控思路，但不是同一技能输出类型。'),
'100':('三星女警输出；重装前排为可换组合','女警每第三发普攻是强化狙击，攻速提高触发频次；4重装靠多名前排的生命值护盾拖时间。','女警本身不吃重装；蜘蛛、人马、洛、大蓝提供4重装。洛＋小炮开花仙，蔚＋希维尔开野兽且蔚＋洛开主宰。','与主宰女警共用女警、希维尔及猎人装备，前排整组切换；高星带装前排的沉没成本决定是否值得换。'),
'106':('三星女警输出；河蟹/瑟庄妮等主宰承担前排','主宰同时给队伍与本职业不同幅度的减伤；猎人提高女警物理输出，并奖励持续攻击同一目标。','蔚＋希维尔带2野兽；洛＋小炮带2花仙。6主宰与3猎人/2花仙之间有人口取舍，不是多主宰永远更强。','与重装女警主C/装备共用度高，是最直接的同核心换前排例子。'),
'110':('三星韦鲁斯主C；凯尔持续输出；日蚀三人组','韦鲁斯用技能物理装，凯尔用攻速/AP混合装；3日蚀奖励队伍独特三星数，后期3月蚀可进一步触发日月双蚀。','月男在这条分支通常是迅射/月蚀连接与余装副C，不应抢走三星韦鲁斯的主装。洛是主宰/重装桥，可为提前双蚀牺牲但要补坦度。','与卡丽蜜儿共用日蚀三人组，与月男共用迅射/月蚀，却不等于主C相同。'),
'115':('宝宝学院条件下的一费三星群；阿卡丽/卡蜜尔按装备分担输出','阿卡丽存在物理/AP形态，按较高属性切换；两种形态与卡蜜尔不应混成同一物理主C。低费三星既吃宝宝学院，也抬日蚀收益。','奥恩＋蕾欧娜提供2护卫；阿卡丽＋卡蜜尔2狂战；凯尔＋韦鲁斯2迅射；瑟庄妮完成3日蚀。','与韦鲁斯路线共享多个低费核心；转向前先比较三星投入、装备形态和宝宝学院条件。'),
'105':('月男是输出锚点；森林前排与纹章是条件模块','月男攻速既影响普攻也影响技能挥击次数；月蚀的攻速/AP可直接服务月男，森林植物与人马控制则增加输出时间。莉莉娅不是原生森林。','霞是迅射/森林/花仙三向桥；人马是森林/重装桥；黛安娜是重装/月蚀桥；莉莉娅与奥恩、霞分别接护卫、花仙。纹章持有者必须显式指定。','与5迅射月男共享主C；森林月蚀无转职理论盘可成立，但不能借用带森林纹章的A评级和统计。'),
'114':('月男主输出＋携迅射纹章的大红副C/前排','来源isCarry漏标月男，不能据此否认标题与装备显示的输出锚点。迅射纹章让近战大红同时贡献射手档位，减少纯后排占位。','月男/霞/韦鲁斯/鸡哥四名原生迅射＋大红转职达到5；黛安娜接2月蚀/2重装；洛后期接主宰/花仙。','无纹章也可用凯尔凑五名原生迅射，但多占一个后排位，不能说是同强度的无损替换。'),
'116':('已进化裁决的三星螳螂＋人马前排','螳螂技能是法术加成魔法伤害，并有孤立目标机制；裁决进化不是天然职业。2裁决提供技能暴击，3/4档增加伤害机制，不能重复把技能暴击当缺口。','奥恩/人马/EZ接3森；人马/黛安娜2重；奥恩/稻草人2护；稻草人/索拉卡2花妖；螳螂/EZ/索拉卡3裁决。','月男不是这套的固定主C，只是与黛安娜开月蚀并消化物理余装的可选位；凯南能升4裁决，优先级要围绕螳螂比较。'),
'112':('地狱火纹章希维尔扩散功能；艾希物理副C、凯南法系副C','希维尔弹射命中多目标，有助携带地狱火机制；3火偏商店运营，5火同时抬灼烧和商店效率。不能把地狱火95标题误写成固定巨龙主C。','蔚/希维尔2野兽，蔚/阿木木2主宰，大蓝/塔里克2重装；韦鲁斯虽低费但可能是5火最后一计数。','与女警共用希维尔、蔚、猎人装备；有火转和高费质量时才能转条件分支。'),
'113':('拉露恩法系输出＋巨龙物理输出＋纳尔功能近战','拉露恩靠施法推进月相，队伍在减伤/增伤间变化；双输出吃不同装备。3森植物、4重装、2斗士与2月蚀共同支撑长战斗。','牛/人/纳3森；人/黛/大蓝/塔4重；牛/纳2斗；黛/拉2月蚀；大蓝＋占2人口巨龙提供3野怪。','这是月蚀—森林—重装联动的另一实际例子，但主C是拉露恩，不是看见月蚀就等于月男。'),
'89':('巨龙物理主C；德莱文持续物理副C；高费前排','巨龙消耗2人口却自带范围攻击、控制及技能变化，必须与被替下的两个位置整体比较。两名高费输出都需要装备，不能只看星级价格。','大蓝＋巨龙达到3野怪；大蓝/塔2重；茂凯/阿木木2主；阿木木/凯南2火。艾翁是技能质量位，不因高费就固定比所有小羁绊强。','与古纳拉共用巨龙、大蓝、塔里克等；选择取决于法装是否支持拉露恩，以及物理装是否足够给双物理C。')}
# Audit proposed boards and preserve exact IDs/traits as evidence.
assert set(routes)==set(cores)=={x['compId'] for x in selected}
audit={'platform':'jcc','patch':'18.4','source_manifest':'manifest.json','boards':[],'conditions':{},'source_roles':{},'shared_members':{}}
for r in selected:
 cid=r['compId'];d=read(P/(cid+'.json'))['data'];audit['conditions'][cid]=d.get('conditions',[])
 audit['source_roles'][cid]={'name':d['name'],'declared_core':[h['heroName'] for h in d['heroes'] if h.get('isCore') and h.get('heroType')==0],'declared_carry':[h['heroName'] for h in d['heroes'] if h.get('isCarry') and h.get('heroType')==0]}
 for lv,st in routes[cid].items():
  b=st['board'];assert len(b)==len(set(b)),(cid,lv,'duplicate');assert all(n in ht for n in b),(cid,lv,[n for n in b if n not in ht]);pop=sum(2 if n=='远古巨龙' else 1 for n in b);assert pop==lv,(cid,lv,pop)
  st['counts'],st['active']=calculate(b,st['emblems'],st['evolve']);audit['boards'].append({'comp':cid,'level':lv,**st})
  if st['emblems']:assert cid in ['105','114','112']
  if st['evolve']:assert '卡兹克' in b and cid=='116'
for n in heroes:
 comps=[r['name'] for r in selected if any(h['heroName']==n and h.get('heroType')==0 for h in read(P/(r['compId']+'.json'))['data']['heroes'])]
 if len(comps)>1:audit['shared_members'][n]=comps
# Test actual breakpoint claims, including missing conditional prerequisites.
M=B('月 霞 人 黛 奥 莉');cnt,act=calculate(M)
assert {x:act[x] for x in ['永恒之森','迅捷射手','月蚀骑士','重装战士','护卫','花仙子']}=={'永恒之森':3,'迅捷射手':2,'月蚀骑士':2,'重装战士':2,'护卫':2,'花仙子':2}
assert calculate(routes['105'][7]['board'])[1]['永恒之森']==3
assert routes['105'][7]['active']['永恒之森']==5
assert calculate(routes['114'][8]['board'])[1]['迅捷射手']==4
assert routes['114'][8]['active']['迅捷射手']==5
assert calculate(routes['112'][7]['board'])[1]['地狱火']==3
assert routes['112'][7]['active']['地狱火']==5
assert calculate(routes['116'][7]['board'])[1]['裁决使']==2
assert routes['116'][7]['active']['裁决使']==3
assert routes['110'][9]['active']['日月双蚀']==1
(P/'logic-audit.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2))

def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+E(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def activefmt(d):return ' · '.join((str(v)+k if k!='日月双蚀' else k) for k,v in d.items()) or '无常规激活羁绊'
def condition(cid):
 d=read(P/(cid+'.json'))['data'];ls=[]
 for x in d.get('conditions',[]):
  z=(eq if x['type']=='equip' else hx).get(str(x['value']),{});ls.append(z.get('name',str(x['value'])))
 if cid=='116':ls.append('卡兹克已进化裁决（机制条件，非来源conditions字段）')
 return '；'.join(ls) or '来源未列额外转职/专属强化条件'
def delta(prev,st):
 if prev is None:return '首次展示该路线的棋盘；沿实际来牌进入，不能跨表默认整盘替换。'
 b=st['board'];a=prev['board'];keep=[x for x in b if x in a];off=[x for x in a if x not in b];on=[x for x in b if x not in a]
 old=prev['active'];new=st['active'];g=[f'{k} {old.get(k,0)}→{v}' for k,v in new.items() if v>old.get(k,0)];loss=[f'{k} {v}→{new.get(k,0)}' for k,v in old.items() if new.get(k,0)<v]
 return '<b>保留：</b>'+E('、'.join(keep) or '无')+'<br><b>换下：</b>'+E('、'.join(off) or '无')+'<br><b>补进：</b>'+E('、'.join(on) or '无')+'<br><b>新增/提升档位：</b>'+E('；'.join(g) or '无；看棋子技能与质量')+'<br><b>损失档位：</b>'+E('；'.join(loss) or '无')
